import{_ as a,o,c as t,a2 as i}from"./chunks/framework.CiKk3sJz.js";const h=JSON.parse('{"title":"漫画 · 第 20 话 多媒体：无需插件的播放管线","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.20-multimedia.md","filePath":"comics/html/EP.20-multimedia.md","lastUpdated":1792579602000}'),d={name:"comics/html/EP.20-multimedia.md"};function r(l,e,c,s,n,m){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-20-话-多媒体-无需插件的播放管线" tabindex="-1">漫画 · 第 20 话 多媒体：无需插件的播放管线 <a class="header-anchor" href="#漫画-·-第-20-话-多媒体-无需插件的播放管线" aria-label="Permalink to &quot;漫画 · 第 20 话 多媒体：无需插件的播放管线&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/09-multimedia">docs/html/09-multimedia.md</a> ｜ 原画：<a href="./EP.20-multimedia.svg">EP.20-multimedia.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，给首屏背景视频加了 <code>autoplay</code>，本地好好的一上线全黑——<code>play()</code> 抛 NotAllowedError 还没捕获；又只放了一个 WebM 源，Safari 用户集体看不到画面。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。讲自动播放策略、source 格式选择、媒体事件流、字幕轨道，以及 picture 与 Web Audio。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p><code>&lt;video&gt;</code> 与 <code>&lt;audio&gt;</code> 是带完整播放管线的原生控件：解码、缓冲、进度、音量、字幕全部内建，JS 通过同一套 HTMLMediaElement 接口控制，移动端还能走硬件解码。<code>&lt;picture&gt;</code> 则是图片领域的响应式决策器，让浏览器按视口、DPR、格式支持自己挑图。Flash 时代结束，但&quot;出声要守规矩、格式要有回退、状态要跟事件&quot;这三条依然要背。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>浏览器的自动播放策略：有声自动播放默认被禁，只有配 <code>muted</code>（或用户与该域名有媒体参与度历史）才放行；<code>autoplay muted playsinline</code> 是短视频信息流的标准姿势，iOS 上没有 playsinline 还会强制全屏接管。违规调用 <code>play()</code> 返回的 Promise 会被 reject 成 NotAllowedError——必须 catch，标准降级是静音后重试。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>&lt;source&gt;</code> 的选择顺序是<strong>第一个浏览器宣称支持的，而不是最好的</strong>：浏览器按顺序检查 MIME type 与解码能力，命中即停，所以优先级格式放前面、MP4/H.264 放最后兜底；type 必须写对，否则浏览器要真下载文件头才知道不支持。媒体事件流是播放器开发的钥匙：<code>loadedmetadata</code> 拿到 duration（进度条最早初始化点）→ <code>canplay</code> 可起播 → <code>timeupdate</code>（约 250ms 一次）驱动进度条 → <code>waiting/playing</code> 切换缓冲菊花；注意<strong>出错时 error 事件触发在具体的 source 元素上，不在 video 上</strong>。<code>&lt;track&gt;</code> 挂 VTT 字幕（subtitles/captions/chapters 等五类 kind），file:// 下常因 CORS 加载失败。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>自定义播放器靠 <code>currentTime</code>（seek）、<code>playbackRate</code>（倍速）、<code>volume</code>（iOS 跟随系统无效），画中画等能力先特性检测。<code>&lt;picture&gt;</code> 本身不渲染，它是源选择器：<code>&lt;source media&gt;</code> 做 art direction（手机竖裁/桌面横裁）、<code>type</code> 做格式渐进（avif→webp→jpg），真正渲染载体与回退永远是内部的 <code>&lt;img&gt;</code>；<code>srcset</code> 的 <code>w</code> 描述符配 <code>sizes</code> 告诉浏览器图片的显示宽度，由浏览器按 DPR × 布局宽选最省的候选。想做频谱可视化，用 <code>createMediaElementSource</code> 把媒体接进 Web Audio 音频图，经 AnalyserNode 读频域数据——<strong>最后必须 connect(audioContext.destination)，否则声音被重定向后无处输出</strong>；AudioContext 还需用户手势 resume，跨域视频画 canvas 要配 crossorigin 否则画布被污染。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>有声自动播放被策略拦：muted playsinline 才全绿，play() 返回的 Promise 必须 catch 降级。</li><li>source 按顺序命中第一个支持的即停、type 必写、MP4/H.264 兜底；error 事件在 source 上。</li><li>picture 用 media/type/srcset+sizes 做决策且必留 img；timeupdate 驱动进度，Web Audio 末端接 destination。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：视频声明了 webm 和 mp4 两个 source，Safari 打不开 webm，为什么通常不会去发请求试一下？如果把 mp4 写在第一个会发生什么？</p><p><strong>答</strong>：因为 <code>&lt;source&gt;</code> 的 <code>type</code> 属性（如 <code>video/webm</code>、<code>video/mp4</code>）让浏览器在<strong>不下载任何字节</strong>的情况下就能对照自身解码能力做判断，不支持就直接跳过看下一个 source——这正是 type 必写的原因（漏写时浏览器只能真去拉文件头再失败，白浪费一次请求）。选择规则是&quot;按出现顺序命中第一个支持的即停&quot;，所以把 MP4 写在第一位时，所有支持 H.264 的浏览器（占绝大多数）都会直接选 MP4，后面的 webm 永远轮不到；这样会失去 WebM 在同等画质下体积更小的优势。主流排列是优先格式（webm/av1 等）在前、MP4/H.264 作为通用兜底放最后。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>video 全属性实验台 + source 多格式 + track 字幕 + 失败占位：<a href="./../../examples/html/09-multimedia/index-01-video-attributes.html">examples/html/09-multimedia/index-01-video-attributes.html</a></li><li>自定义播放器：播放/进度/音量/倍速 + 媒体事件流日志：<a href="./../../examples/html/09-multimedia/index-02-js-controls.html">index-02-js-controls.html</a></li><li>picture 响应式 + Canvas captureStream + Web Audio 频谱可视化：<a href="./../../examples/html/09-multimedia/index-03-picture-canvas-audio.html">index-03-picture-canvas-audio.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 21 话（HTML 篇完结篇）《原生造好的轮子》——dialog、Popover、inert、template 与资源提示，少写一千行样板代码。</p>',22)])])}const p=a(d,[["render",r]]);export{h as __pageData,p as default};
